SELECT * FROM proj_result_subscription WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId}
AND plan_version_id=#{query.planVersionId} AND execution_id=#{query.executionId}
AND subscription_key=#{query.subscriptionKey} AND deleted=0 FOR UPDATE

SELECT * FROM proj_result_subscription WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId}
  AND channel_id=#{query.channelId} AND id > #{query.afterId} AND phase != 'RETIRED' AND deleted=0
ORDER BY id LIMIT #{query.limit}

