UPDATE proj_result_subscription SET phase='RETIRED',version=version+1
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.id}
  AND version=#{query.expectedVersion} AND phase != 'RETIRED' AND deleted=0
